window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"JsP2fB162Fs","speaker":"Daniel Francisco Chapo","role":"President","country":"Mozambique","region":"Africa","url":"https://www.youtube.com/watch?v=JsP2fB162Fs","date":"20260923","title":"🇲🇿 Mozambique -  President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1421,"words":2304,"counts":{"claims":30,"promises":5,"attacks":1},"topics":[{"topic":"Mozambique climate","share":0.115,"seconds":163},{"topic":"Mozambique economy","share":0.0957,"seconds":136},{"topic":"Mozambique security","share":0.0885,"seconds":126},{"topic":"UN leadership","share":0.0638,"seconds":91},{"topic":"UNSC reform","share":0.0638,"seconds":91},{"topic":"UNGA session","share":0.0557,"seconds":79},{"topic":"Middle East conflict","share":0.0503,"seconds":72},{"topic":"Mozambique finance","share":0.0497,"seconds":71},{"topic":"Multilateral cooperation","share":0.0492,"seconds":70},{"topic":"Technology","share":0.0482,"seconds":69},{"topic":"UN reform","share":0.0482,"seconds":68},{"topic":"Mozambique governance","share":0.0475,"seconds":67},{"topic":"Mozambique infrastructure","share":0.0471,"seconds":67},{"topic":"Mozambique diplomacy","share":0.0457,"seconds":65},{"topic":"Development funding","share":0.0447,"seconds":64},{"topic":"UNGA ceremony","share":0.044,"seconds":63},{"topic":"Cuba","share":0.0431,"seconds":61}],"timeline":[[1,66,null],[67,130,"UNGA ceremony"],[131,211,"UNGA session"],[212,281,"Technology"],[282,347,"Mozambique diplomacy"],[347,438,"UN leadership"],[438,500,"Mozambique security"],[501,573,"Middle East conflict"],[574,635,"Cuba"],[636,700,"Development funding"],[700,768,"Mozambique governance"],[769,833,"Mozambique security"],[835,898,"Mozambique economy"],[899,970,"Mozambique finance"],[971,1044,"Mozambique economy"],[1045,1112,"Mozambique infrastructure"],[1113,1190,"Mozambique climate"],[1193,1279,"Mozambique climate"],[1279,1370,"UNSC reform"],[1371,1440,"UN reform"],[1441,1511,"Multilateral cooperation"],[1513,1529,null]],"stances":{"UNGA ceremony":"Daniel Francisco Chapo congratulates the new President of the General Assembly and expresses Mozambique's full support while acknowledging the predecessor's work.","UNGA session":"Daniel Francisco Chapo states that the UN's founding promise of cooperation has historically protected lives but now faces severe tests from modern conflicts and crises.","Technology":"Daniel Francisco Chapo states that the digital revolution, demographic changes, and value chain organization are transforming economies at an unprecedented pace while highlighting the world's current state of being interconnected yet fragmented.","Mozambique diplomacy":"Daniel Francisco Chapo states that Mozambique values multilateralism and the United Nations based on its own historical experience.","UN leadership":"Daniel Francisco Chapo commends Secretary-General Antonio Guterres for his tenure and calls for continuing the work of strengthening the UN.","Mozambique security":"Daniel Francisco Chapo calls for strengthening compliance with conflict prevention mechanisms and international law to address terrorism and transnational crime.","Middle East conflict":"Daniel Francisco Chapo supports a two-state solution for Palestine and Israel, reaffirms the principle of self-determination, and opposes unilateral coercive measures against people.","Cuba":"Daniel Francisco Chapo reiterates support for ending the economic, commercial, and financial blockade against Cuba and calls for the unconditional lifting of sanctions against Zimbabwe and other countries.","Development funding":"Daniel Francisco Chapo argues that accelerating SDG implementation requires predictable financing and a fairer international financial architecture.","Mozambique governance":"Daniel Francisco Chapo states that Mozambique is committed to strengthening democratic institutions and conducting an inclusive national dialogue led by Mozambicans.","Mozambique economy":"Daniel Francisco Chapo states that Mozambique is committed to transforming its potential into shared prosperity by valorizing resources and investing in human capital, particularly youth and women.","Mozambique finance":"Daniel Francisco Chapo states that Mozambique seeks partnerships to build national capacity and generate employment while diversifying its partnerships in a sovereign manner.","Mozambique infrastructure":"Daniel Francisco Chapo states that Mozambique is building electricity interconnectors and border crossing points to integrate with neighboring countries, while advocating for fair financing to support development goals.","Mozambique climate":"Daniel Francisco Chapo argues that Mozambique requires concessional financing and fulfilled commitments from developed nations to address climate change vulnerabilities, emphasizing the need for increased funding for adaptation and resilience.","UNSC reform":"Daniel Francisco Chapo asserts that Africa must be granted permanent membership in the UN Security Council to correct representation imbalances.","UN reform":"Daniel Francisco Chapo advocates for strengthening international cooperation and equipping the UN with greater capacity to address current challenges and serve future generations.","Multilateral cooperation":"Daniel Francisco Chapo asserts that dialogue and the strengthening of the United Nations are the clear path forward, rejecting the use of force to impose decisions."},"claims":[{"t":131,"quote":"We the people together has the most comprehensive expression of our collective responsibility towards the 81 years ago in one in the face of devastation caused by war, the humanity chose cooperation over confrontation, the law of force and hope of fear.","topic":"UNGA session","kind":"fact"},{"t":169,"quote":"It has protected millions of lives in the whole world and it gave voice to those that during many time remained on the margin of international decisions.","topic":"UNGA session","kind":"fact"},{"t":214,"quote":"the digital revolution, the demographic changes and the organization of the value chains are transforming our economies every day in the society at an unprecedented pace.","topic":"Technology","kind":"fact"},{"t":231,"quote":"Never has the world been so interconnected and at the same time so fragmented like today.","topic":"Technology","kind":"fact"},{"t":299,"quote":"This organization, this organization has stood by our people at decisive moments of its history on the path to our national independence as a people in the pursuit and building of peace in Mosmbique and in the national reconstruction in the responding to natural disasters and in the promotion of sustainable development.","topic":"Mozambique diplomacy","kind":"fact"},{"t":377,"quote":"His legacy is in our point of view unquestionable, positive and marked by transformative achievements of this organization.","topic":"UN leadership","kind":"fact"},{"t":409,"quote":"today the three pillars amongst which the UN work, peace and security, development and human rights are under unprecedented","topic":"UN leadership","kind":"fact"},{"t":438,"quote":"terrorism and the expansion of transnational organized crime. These challenges amongst others must lead us to strengthen compliance with the promotion of the mechanism for prevention and peaceful resolution of conflict","topic":"Mozambique security","kind":"fact"},{"t":512,"quote":"Living side by side with peace and security with Israel has a legitimate and lasting path forward.","topic":"Middle East conflict","kind":"fact"},{"t":524,"quote":"The principle of self-determination of the people enshrined in the United Nation charter as far back as 19 45 remain so valid as ever.","topic":"Middle East conflict","kind":"fact"},{"t":574,"quote":"We thus reiterate our position in the support of ending of economic, commercial and financial blockade imposed to against Kuba.","topic":"Cuba","kind":"fact"},{"t":626,"quote":"In the area of development, we are still far from fulfilling the promise of the 2030 agenda.","topic":"Cuba","kind":"fact"},{"t":636,"quote":"With less than four years until the deadline, millions of people remain deprived of basic opportunities, water, energy, infrastructure, and others.","topic":"Development funding","kind":"fact"},{"t":728,"quote":"Mr. President in Mosmbique, we are committed to consolidating strengthening democratic institutions and conducting an inclusive national dialogue led by the Mozambicans uh initiatives that genuinely moan to deepen reconciliation, national unity, the peace and the reforms that are necessary with the support of our partners, international partners while respecting the national ownership in Cabel Gadu.","topic":"Mozambique governance","kind":"self_credit"},{"t":769,"quote":"We have made progress in fighting terrorism and strengthening thanks to the efforts of the defense and security and the support of SADC, the European Union, Rwanda and Tanzania.","topic":"Mozambique security","kind":"fact"},{"t":823,"quote":"within the framework of the national development plan 2025 and 20 25 to 2044.","topic":"Mozambique security","kind":"fact"},{"t":843,"quote":"investing in human capital especially in the youth and women which are the majority","topic":"Mozambique economy","kind":"fact"},{"t":885,"quote":"The mobilization of income and investment in our biggest asset which is the talent of the Mozambique people and the talent of the African people","topic":"Mozambique economy","kind":"self_credit"},{"t":899,"quote":"Our location in the Indian Ocean, our logistic corridors and our agricultural potential, energy and mineral uh make Mozambique a strategic platform for the investment and regional integration.","topic":"Mozambique finance","kind":"fact"},{"t":975,"quote":"It is rich in resources yet retains little of the value that it generates.","topic":"Mozambique economy","kind":"fact"},{"t":1013,"quote":"In this context, the regional takes a strategic importance as it amplifies markets, creates economies, integrates productive challenges, attracts investment and stimulate innovation","topic":"Mozambique economy","kind":"fact"},{"t":1045,"quote":"This vision translate into progress on electricity interconnectors with neighboring countries as well as in onetop borders crossing points that we are building.","topic":"Mozambique infrastructure","kind":"fact"},{"t":1081,"quote":"with less than four years remaining for the achievement of the 23rd agenda, the developing country continue to face high financing costs, rising depth, and limited access to resources to invest in their own development.","topic":"Mozambique infrastructure","kind":"fact"},{"t":1134,"quote":"Mozambique as one of the countries that is more vulnerable in the world. climate change.","topic":"Mozambique climate","kind":"fact"},{"t":1141,"quote":"They translate into losses in life, displaced families, destroyed crops and damaged The cyclones demonstrate that resilience is now an environmental, economic and food security uh social for development issue and increasingly one of peace and security in all the world.","topic":"Mozambique climate","kind":"fact"},{"t":1193,"quote":"Mozambi remains highly vulnerable to extreme weather events, floods, and uh we are concerned with the El Nino that might have potential severe impact in the central and southern parts of the country especially when it comes to droughts, food insecurity and livelihood.","topic":"Mozambique climate","kind":"fact"},{"t":1229,"quote":"humanitarian needs are already facing a severe funding shortfall in the whole world.","topic":"Mozambique climate","kind":"fact"},{"t":1320,"quote":"Africa cannot continue to be in a center of the security council agenda while remaining absent from its rank of permanent members.","topic":"UNSC reform","kind":"fact"},{"t":1425,"quote":"Your excellencies the 81 81 years ago the founders of this organization entrusted humanity with a promise of peace, cooperation and dignity and most of all hope.","topic":"UN reform","kind":"fact"},{"t":1467,"quote":"This organization is the most comprehensive expression of our collective responsibility and our commitment to multi multilateralism to the service of the humanity.","topic":"Multilateral cooperation","kind":"fact"}],"promises":[{"t":461,"quote":"what we are going to do at the international law in the light of United Nation Charter including respect for those sovereignity and territorial integrity of our states.","topic":"Mozambique security","kind":"promise"},{"t":487,"quote":"In this way, we will be able to address conflicts that persist around the world, including in some countries and regions of our continent, Africa.","topic":"Mozambique security","kind":"promise"},{"t":853,"quote":"We also want to increase value to the natural resources","topic":"Mozambique economy","kind":"promise"},{"t":857,"quote":"We also want to modernize our agriculture, promote industrialization, develop tourism, expand access to energy, invest infrastructures, education, health, science and technology, digitalization and in the economy in general","topic":"Mozambique economy","kind":"promise"},{"t":935,"quote":"Mozambique will continue to diversify its partnership in sovereign way, transparent and mutual beneficial manner working with all the parties in the light of the national priorities.","topic":"Mozambique finance","kind":"promise"}],"attacks":[{"t":558,"quote":"we oppose to imposition of unilateral co co measures which continues to penalize entire people in clear violation of the affirmation charter of the UN.","topic":"Middle East conflict","target":"Unilateral coercive measures"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":null,"text":"The assembly will now hear an address by His Excellency Daniel Francisco Chapo, President of the Republic of Mosmbique. I request protocol to escort his excellency and invite him to address the Your Excellency, heads of states and the Your Excellency Khalil Raman, President of the 81st session of the United Nation General Assembly. Your Excellency Antonio Gautes, Secretary General of the United Nations. Your Excellencies, dear ministers here, president present representing the heads of states."},{"t":67,"topic":"UNGA ceremony","text":"Allow me to start by congratulating you, Mr. President, on your election to preside over the work of this assembly and assure you the full support of the Republic of Mosmbique. We also recognize the work carried out by your predecessor, her excellency Analena in the service of this organization whose contribution we greatly value. Mr. The topic chosen for this session, restoring trust, managing a united nation that benefits all, invites us to return to the opening words of the United Nations charter, simple words, yet perhaps amongst the powerful ever inscribed in an international treaty."},{"t":131,"topic":"UNGA session","text":"We the people together has the most comprehensive expression of our collective responsibility towards the 81 years ago in one in the face of devastation caused by war, the humanity chose cooperation over confrontation, the law of force and hope of fear. That promise has shaped generations. It has protected millions of lives in the whole world and it gave voice to those that during many time remained on the margin of international decisions. however, the promise that we face is one of the toughest tests as we live in a world marked by protected wars, growing geopolitical persistent humanitarian crisis, severe weather events, and other highly complex challenges at the world."},{"t":212,"topic":"Technology","text":"At the same time, your excellency, the digital revolution, the demographic changes and the organization of the value chains are transforming our economies every day in the society at an unprecedented pace. Never has the world been so interconnected and at the same time so fragmented like today. And it's precisely in this contest that the theme of this session takes an important Restoring trust requires consistency between the principle we proclaim as leaders and the decisions we make. It requires the fair application of international law and concrete results that translate into improvement in the lives of the people in the whole world. In short, restoring trust means renewing the promise made 81 years ago."},{"t":282,"topic":"Mozambique diplomacy","text":"I repeat, we the people, Mr. President Mozambique knows from its own experience the value of multilateralism and the value of the United Nations. This organization, this organization has stood by our people at decisive moments of its history on the path to our national independence as a people in the pursuit and building of peace in Mosmbique and in the national reconstruction in the responding to natural disasters and in the promotion of sustainable development. today in the process of the national dialogue. Thank you so much. UN the trust of Mozambi is uh result of a living memory of the Mozambi people."},{"t":347,"topic":"UN leadership","text":"It is in this period that Mozambique would like to commend the leadership of the secretary general Antonio Gutes whose tenure uh coincided with a period marked with enormous global challenges and in which the limits of multilateralism were put to test. He leaves behind a robust organization that is prepared to a better respond to the challenges of our time. His legacy is in our point of view unquestionable, positive and marked by transformative achievements of this organization. Thus the best tribute we can pay to his legacy is to continue the work of strengthening this organization because no generation is going to inherit uh united nation as a finished legacy. Your excellencies, today the three pillars amongst which the UN work, peace and security, development and human rights are under unprecedented In the realm of peace, security, we witness gloriferation of conflicts, worsening of civilian suffering and the of"},{"t":438,"topic":"Mozambique security","text":"terrorism and the expansion of transnational organized crime. These challenges amongst others must lead us to strengthen compliance with the promotion of the mechanism for prevention and peaceful resolution of conflict as well as what we are going to do at the international law in the light of United Nation Charter including respect for those sovereignity and territorial integrity of our states. the human rights and international cooperation factors that are in fact to be truthful. In this way, we will be able to address conflicts that persist around the world, including in some countries and regions of our continent, Africa."},{"t":501,"topic":"Middle East conflict","text":"It is also this that under analyze the support of our defense for solutions for two states for Palestine. Living side by side with peace and security with Israel has a legitimate and lasting path forward. The principle of self-determination of the people enshrined in the United Nation charter as far back as 19 45 remain so valid as ever. It is in this context that we reaffirm our principled position in support the cause for the safari people. The value enshrined in the United Nation CH charter elevate this organization to be the epicenter for global multilateralism. For this reason, we oppose to imposition of unilateral co co measures which continues to penalize entire people in clear violation of the affirmation charter of the UN."},{"t":574,"topic":"Cuba","text":"We thus reiterate our position in the support of ending of economic, commercial and financial blockade imposed to against Kuba. Likewise, we wish to express our solidarity with the brotherly people of Zimbabwe and reiterate our position in favor of unconditional lifting of sanctions against Zimbabwe and the other countries in the world. We also advocate for mutual bene benefical economic cooperation based on respect for sovereignity for each state for the equality between the states and the freedom of choice for the people during the electoral process. In the area of development, we are still far from fulfilling the promise of the 2030 agenda."},{"t":636,"topic":"Development funding","text":"With less than four years until the deadline, millions of people remain deprived of basic opportunities, water, energy, infrastructure, and others. Thus, it's important to accelerate the implementation of the commitment made under the SDGs which requires predictable, accessible and sustainable financing. It is also requires a fair international financial agreeature, more fair sustainable debt relief, greater transfer of technology, international trade that is more balanced and investments that can transform the potential into prosperity as well as adhere to the principle of common responsibility but differentiated responsibility."},{"t":700,"topic":"Mozambique governance","text":"ilities. Similarly, in the field of human rights, it's also important to promote a balanced and impartial and coherent approach based on the principles of universality and equal treatment between the states. Promoting these rights should prioritize constructive dialogue, cooperation, and the strengthening of our institutions. Mr. President in Mosmbique, we are committed to consolidating strengthening democratic institutions and conducting an inclusive national dialogue led by the Mozambicans uh initiatives that genuinely moan to deepen reconciliation, national unity, the peace and the reforms that are necessary with the support of our partners, international partners while respecting the national ownership in Cabel Gadu."},{"t":769,"topic":"Mozambique security","text":"We have made progress in fighting terrorism and strengthening thanks to the efforts of the defense and security and the support of SADC, the European Union, Rwanda and Tanzania. However, the stabilization remains incomplete and requires a concentrated response and a greater international cooperation for the fight against We are grateful for the solidarity we have received and we call for a more predictable and coordinated international support to consolidate security, stabilization, and development in the affected areas where the local force is still doing the work in the fight against terrorism. within the framework of the national development plan 2025 and 20 25 to 2044."},{"t":835,"topic":"Mozambique economy","text":"Mozambi is committed to transforming its potential into shared prosperity for the people through the valorization of resources and investing in human capital especially in the youth and women which are the majority. We also want to increase value to the natural resources. We also want to modernize our agriculture, promote industrialization, develop tourism, expand access to energy, invest infrastructures, education, health, science and technology, digitalization and in the economy in general. Natural resources should contribute to the economic diversification of our economy. The mobilization of income and investment in our biggest asset which is the talent of the Mozambique people and the talent of the African people."},{"t":899,"topic":"Mozambique finance","text":"Our location in the Indian Ocean, our logistic corridors and our agricultural potential, energy and mineral uh make Mozambique a strategic platform for the investment and regional integration. We therefore seek uh partnerships that build national capacity, promote local content, respect the environment and generate employment especially for the young people and women. Mozambique will continue to diversify its partnership in sovereign way, transparent and mutual beneficial manner working with all the parties in the light of the national priorities. This is also the Africa's ambition to be the architect of their own destiny to participate in setting the rules and to fully benefit from the wealth it helps to create."},{"t":971,"topic":"Mozambique economy","text":"Africa faces however a paradox. It is rich in resources yet retains little of the value that it generates. Therefore, investment must involve and from simple extraction to the transformation, creation of value chain at the local level, moving from transactions to partnerships, from dependence to capacity building and from exportation of resources to the construction of value chains both national, regional and international. In this context, the regional takes a strategic importance as it amplifies markets, creates economies, integrates productive challenges, attracts investment and stimulate innovation and also transforming the potent the economic potential into uh concrete opportunity especially for its people and young people in particular in Mozambique."},{"t":1045,"topic":"Mozambique infrastructure","text":"This vision translate into progress on electricity interconnectors with neighboring countries as well as in onetop borders crossing points that we are building. The integration is built through roads that bring people closer with energy that crosses borders, infrastructures that transform neighboring communities into single communities, a transformation that requires fair and sustainable financing Your excellencies, with less than four years remaining for the achievement of the 23rd agenda, the developing country continue to face high financing costs, rising depth, and limited access to resources to invest in their own development. We continue to advocate for a fair international architecture, more predictable and accessible financing and sustainable to sustainable solutions for the depth."},{"t":1113,"topic":"Mozambique climate","text":"It is also necessary that the access to concessional financing take into account the country's beyond just the income that uh we also want to make sure that developed countries can fully fulfill their commitment to development and financial action for Mozambique as one of the countries that is more vulnerable in the world. climate change. They translate into losses in life, displaced families, destroyed crops and damaged The cyclones demonstrate that resilience is now an environmental, economic and food security uh social for development issue and increasingly one of peace and security in all the world. We therefore reiterate the need to increase funding for adaptation, facilitate access to climate funds, operationalize the loss and damage mechanisms and invest in early warning systems and resilient infrastructure."},{"t":1193,"topic":"Mozambique climate","text":"Mozambi remains highly vulnerable to extreme weather events, floods, and uh we are concerned with the El Nino that might have potential severe impact in the central and southern parts of the country especially when it comes to droughts, food insecurity and livelihood. The preparedness and international cooperation will be essential to mitigate these impacts in a context where humanitarian needs are already facing a severe funding shortfall in the whole world. Mr. President digital transformation remains or demands the same solidarity that we are talking about because Africa must not limit itself to supplying the minerals that fuels the world innovation hubs. We need to have investment in computing capacity, scientific research, training of young people in Africa, technology transfer, governance, uh, ethics for AI in the spirit of partnership that build capacity and promotes autonomy of our sovereignity states."},{"t":1279,"topic":"UNSC reform","text":"Thus, Mozambi reiterates its support for the objectives of the UN8 initiative to make this organization more effective, coherent, representative, and suited to the challenges of our time. Reform must be embraced as political commitment focused on concrete results. Reforms must also correct imbalances in representation of global governance. In this regard, Africa cannot continue to be in a center of the security council agenda while remaining absent from its rank of permanent members. Africa must be a permanent member of the security council of the UN. We therefore reaffirm the common African position uh related to the reform of the United Nation Security Council based on the Euluini consensus and the search declaration under which no fewer than two permanent seats with all prerogatives and privileges including the veto as long as it exists and five non-permanent seats are allocated to"},{"t":1371,"topic":"UN reform","text":"Africa. The contribution that Mosabi wishes to make to the debate on this assembly has the objective of restoring trust through peace, manage transformation through inclusion and produce result through a coherent uh actions at the national, regional and global levels. To this it's important to strengthen international cooperation and equip the UN with greater capacity to address the challenges of the present and make sure that the future generations can have a stronger organization that one we have received. An organization equal to the challenges of our time capable of serving the people with dignity, protecting the planet and promoting a share prosperity at international level. Your excellencies the 81 81 years ago the founders of this organization entrusted humanity with a promise of peace, cooperation and dignity and most of all hope."},{"t":1441,"topic":"Multilateral cooperation","text":"Today that responsibility uh falls to us and the path remains very clear. Dialogue, and continued strengthening to the role of the United Nations and never the use of force in order to impose decisions. This organization is the most comprehensive expression of our collective responsibility and our commitment to multi multilateralism to the service of the humanity. Mr. President, allow me to conclude by returning to the opening words of our Magna Carta or charter. We the people. Those words do not belong to the past but their commitment to a future which the United Nations remain the expression of our shared responsibility towards uh unity in the humanity."},{"t":1513,"topic":null,"text":"Thank you so much for your kind On behalf of the assembly, I wish to thank the president of the Republic of Mosmbique."}],"compare":[{"topic":"UN & its reform","share":0.2421,"mean":0.2046,"rank":71,"others":170},{"topic":"Mozambique","share":0.1403,"mean":0.0,"rank":1,"others":0},{"topic":"Middle East","share":0.0526,"mean":0.0071,"rank":15,"others":19},{"topic":"International Law & Order","share":0.0515,"mean":0.0604,"rank":88,"others":102},{"topic":"Artificial Intelligence","share":0.0505,"mean":0.0505,"rank":76,"others":83},{"topic":"Global Economy","share":0.0468,"mean":0.0144,"rank":32,"others":31},{"topic":"Cuba","share":0.045,"mean":0.0112,"rank":19,"others":23}]};
